import { Component, Host, h } from "@stencil/core";

/**
 * @since 0.0.12
 * @status deprecated
 *
 */
@Component({
	tag: "hbr-contribution-model",
	styleUrl: "hbr-contribution-model.scss",
	shadow: true,
})
export class HbrContributionModel {
	componentDidLoad() {
		void this.buildIndex();
	}

	async buildIndex() {
		const [{ buildContributionIndex }, { config }] = await Promise.all([
			import("./buildContributionIndex"),
			import("./data"),
		]);

		buildContributionIndex(config);
	}

	render() {
		console.error("hbr-workflow-step is deprecated in January 2025");
		return (
			<Host>
				<slot />
			</Host>
		);
	}
}
